insert into public.jada_sections (key, content) values ('live', '{"label":"Upcoming shows","heading":"Live *Session*","titleArt":{"src":"/media/live-session-title.webp","alt":"Live Session"},"intro":"Catch JADA live with her all-female band.","poster":{"src":"/media/live-poster.webp","alt":"JADA Live poster with show dates in October and November"},"events":[{"date":"2026-10-21","time":"20:00","title":"The Spotlight Lounge","note":"Live music showcase presented by Accelerando Records","venue":"The Fabwick","city":"London","price":"From £9.38","ticketUrl":"https://www.eventbrite.co.uk/e/the-spotlight-lounge-live-music-showcase-fabwick-tickets-2002210644937?aff=jada","ticketLabel":"Tickets"},{"date":"2026-11-19","time":"19:00","title":"JADA: Past & Present – The Album Experience","note":"Presented by Synapse Recordings","venue":"The Upper Place","city":"London","price":"Free entry","ticketUrl":"https://www.eventbrite.com/e/jada-past-present-the-album-experience-tickets-2002522977131","ticketLabel":"Get free tickets"}],"emptyMessage":"New dates are on the way. Join the mailing list to hear about them first."}'::jsonb) on conflict (key) do nothing;
insert into public.jada_sections (key, content) values ('about', '{"label":"JADA · The artist","heading":"Music made\nto be *felt.*","body":"JADA creates from the meeting point of musicianship, live performance and visual storytelling. Her world is expressive, soulful and built around connection.","linkLabel":"Meet JADA","image":{"src":"/media/jada-portrait.webp","alt":"JADA portrait"}}'::jsonb) on conflict (key) do nothing;
insert into public.jada_sections (key, content) values ('release', '{"label":"Current release","heading":"Out now.","title":"That''s What\nI *Like.*","body":"JADA feat. MichaelTheVillain. Step into the latest chapter through the single, lyric film and visual world surrounding the release.","cover":{"src":"/media/thats-what-i-like-cover.webp","alt":"That''s What I Like cover art"},"titleArt":{"src":"/media/thats-what-i-like-title.webp","alt":"That''s What I Like"},"listenLabel":"Listen now","listenUrl":"https://hypeddit.com/j02cru","videoLabel":"Watch lyric video","videoId":"oi8ZUCHzJcc","menuCaption":"Current release · That''s What I Like feat. MichaelTheVillain"}'::jsonb) on conflict (key) do nothing;
insert into public.jada_sections (key, content) values ('album', '{"label":"Featured project","title":"Past &\n*Present.*","body":"Written from lessons learned across childhood and young adulthood, the project explores empowerment, love, vulnerability and growth. For JADA, telling the story through music became part of finding confidence in herself.","linkLabel":"Explore the project","linkUrl":"https://hypeddit.com/j02cru","cover":{"src":"/media/past-and-present-cover.webp","alt":"Past & Present album artwork"},"titleArt":{"src":"/media/past-and-present-title.webp","alt":"Past & Present"},"quoteLabel":"In JADA''s words","quote":"“This project represents *growth.* Telling my story in music form has healed me and allowed me to find a new confidence in myself.”"}'::jsonb) on conflict (key) do nothing;
insert into public.jada_sections (key, content) values ('visuals', '{"label":"Films · campaign · process","heading":"Visuals.","linkLabel":"View the gallery"}'::jsonb) on conflict (key) do nothing;
insert into public.jada_sections (key, content) values ('journal', '{"label":"From the journal","heading":"Journal.","intro":"Notes from the studio, the stage and everything in between.","linkLabel":"Read the journal"}'::jsonb) on conflict (key) do nothing;
insert into public.jada_sections (key, content) values ('press', '{"label":"Mini press kit","heading":"JADA.","lead":"Singer, songwriter, multi-instrumentalist and creative entrepreneur from Hertfordshire, England.","body":"Rooted in powerful vocals, musicianship and a deep love for live performance, JADA creates music and experiences centred around storytelling, emotional connection and creative expression. Her musical journey began in church and has evolved into a multidisciplinary practice combining live music, movement, visual storytelling and audience connection.","image":{"src":"/media/press-photo.webp","alt":"JADA press photo"},"stats":[{"title":"5 instruments","detail":"Voice · Guitar · Bass · Drums · Piano"},{"title":"Artist + founder","detail":"Synapse Recordings"},{"title":"Press ready","detail":"Bio · photos · music · videos"}],"assetsLabel":"Open press assets","assetsUrl":"https://drive.google.com/drive/folders/1SRvnrz6tgEajEGSqfZgjzLK_iWQHAhLk"}'::jsonb) on conflict (key) do nothing;
insert into public.jada_sections (key, content) values ('booking', '{"label":"Bookings","heading":"Book\n*JADA.*","intro":"For live performances, private and corporate events, session work and creative collaborations. Share a few details and the team will be in touch.","offerings":[{"title":"Live performance","detail":"Full band or stripped-back acoustic sets for festivals, venues and showcases."},{"title":"Private & corporate events","detail":"Weddings, launches, galas and celebrations, shaped around the room."},{"title":"Session work","detail":"Vocals, guitar, bass, drums and piano for records and live shows."},{"title":"Brand collaborations","detail":"Campaigns, content and partnerships that fit JADA''s world."}],"email":"","successMessage":"Thank you. Your request is with the team and we''ll be in touch soon."}'::jsonb) on conflict (key) do nothing;
insert into public.jada_sections (key, content) values ('join', '{"label":"Personal updates from JADA","heading":"Stay\n*close.*","body":"New music, visual releases, live dates and personal updates from JADA. Join the list and stay connected beyond the feed.","note":"Mailing list powered by Brevo. Unsubscribe at any time.","successMessage":"Thank you for signing up to Jada''s Mailing List!"}'::jsonb) on conflict (key) do nothing;
